    "\n"
    "  <footer>ESP32-S3 · 设备与手机需在同一 WiFi</footer>\n"
    "</main>\n"
    "<div class=\"toast\" id=\"toast\"></div>\n"
    "\n"
    "<script>\n"
    "const $ = s => document.querySelector(s);\n"
    "const logEl = $('#log');\n"
    "\n"
    "function log(msg, bad) {\n"
    "  const t = new Date().toLocaleTimeString('zh-CN', {hour12: false});\n"
    "  logEl.innerHTML = `<span style=\"opacity:.55\">${t}</span> ${bad ? '<b>' + msg + '</b>' : msg}\\n` + logEl.innerHTML;\n"
    "  if (logEl.childElementCount > 60) logEl.removeChild(logEl.lastChild);\n"
    "}\n"
    "\n"
    "function toast(msg) {\n"
    "  const t = $('#toast');\n"
    "  t.textContent = msg;\n"
    "  t.classList.add('show');\n"
    "  clearTimeout(t._timer);\n"
    "  t._timer = setTimeout(() => t.classList.remove('show'), 1500);\n"
    "}\n"
    "\n"
    "let busy = false;\n"
    "function setBusy(b) {\n"
    "  if (b === busy) return;\n"
    "  busy = b;\n"
    "  document.querySelectorAll('button').forEach(el => el.disabled = b);\n"
    "}\n"
    "\n"
    "const DUR = () => ({\n"
    "  pw: +$('#pw').value,\n"
    "  vw: +$('#vw').value,\n"
    "  fbPw: +$('#fbPw').value,\n"
    "  fbHold: +$('#fbHold').value,\n"
    "  off: $('#fbOff').checked ? 1 : 0,\n"
    "});\n"
    "\n"
    "async function request(url, label) {\n"
    "  try {\n"
    "    const r = await fetch(url, {cache: 'no-store'});\n"
    "    let j = {};\n"
    "    try { j = await r.json(); } catch (e) {}\n"
    "    if (!r.ok) {\n"
    "      log(label + ' ✕ ' + (j.error || r.status), true);\n"
    "      toast(j.error === 'action_in_progress' ? '上一个操作还没完成' : '请求失败');\n"
    "      return;\n"
    "    }\n"
    "    log(label + ' ✓');\n"
    "    toast(label + ' 已发送');\n"
    "    setBusy(true);\n"
    "  } catch (e) {\n"
    "    log(label + ' ✕ ' + e.message, true);\n"
    "    toast('连接失败');\n"
    "  }\n"
    "}\n"
    "\n"
    "function actionUrl(act) {\n"
    "  const d = DUR();\n"
    "  switch (act) {\n"
    "    case 'power':    return ['/power?ms=' + d.pw, '按电源 ' + d.pw + 'ms'];\n"
    "    case 'voldown':  return ['/voldown?ms=' + d.vw, '音量减 ' + d.vw + 'ms'];\n"
    "    case 'volup':    return ['/volup?ms=' + d.vw, '音量加 ' + d.vw + 'ms'];\n"
    "    case 'fastboot': return ['/fastboot?power=' + d.fbPw + '&hold=' + d.fbHold + '&off=' + d.off,\n"
    "                             'fastboot ' + d.fbPw + '/' + d.fbHold + 'ms'];\n"
    "    case 'on':       return ['/on', '开机'];\n"
    "    case 'off':      return ['/off', '强制关机'];\n"
    "    case 'reboot':   return ['/reboot', '重启'];\n"
    "    default:         return ['/' + act, act];\n"
    "  }\n"
    "}\n"
    "document.addEventListener('click', e => {\n"
    "  const btn = e.target.closest('button[data-act]');\n"
    "  if (!btn || btn.disabled) return;\n"
    "  if (btn.dataset.confirm && !confirm(btn.dataset.confirm)) return;\n"
    "  if (btn.dataset.act === 'status') {\n"
    "    fetchStatus().then(busyNow => { if (busyNow !== null) toast('状态已刷新'); });\n"
    "    return;\n"
    "  }\n"
    "  const [url, label] = actionUrl(btn.dataset.act);\n"
    "  request(url, label);\n"
    "});\n"
    "\n"
    "document.querySelectorAll('input[data-out]').forEach(input => {\n"
    "  const out = $('#' + input.dataset.out);\n"
    "  const sync = () => {\n"
    "    out.value = input.value + ' ms';\n"
    "    if (input.id === 'vw') {\n"
    "      document.querySelectorAll('.vw-lbl').forEach(el => el.textContent = '按住 ' + input.value + ' ms');\n"
    "    }\n"
    "  };\n"
    "  input.addEventListener('input', sync);\n"
    "  sync();\n"
    "});\n"
    "\n"
    "function fmtUptime(s) {\n"
    "  if (s < 60) return s + ' 秒';\n"
    "  if (s < 3600) return Math.floor(s / 60) + ' 分 ' + (s % 60) + ' 秒';\n"
    "  return Math.floor(s / 3600) + ' 时 ' + Math.floor((s % 3600) / 60) + ' 分';\n"
    "}\n"
    "\n"
    "async function fetchStatus() {\n"
    "  try {\n"
    "    const j = await (await fetch('/status', {cache: 'no-store'})).json();\n"
    "    $('#pill').className = 'pill ' + (j.busy ? 'busy' : 'on');\n"
    "    $('#pillTxt').textContent = j.busy ? '执行中' : '在线';\n"
    "    $('#sub').textContent = (j.ssid || '未连接') + ' · ' + j.ip +\n"
    "      ' · 已运行 ' + fmtUptime(j.uptime_s);\n"
    "    setBusy(!!j.busy);\n"
    "    return !!j.busy;\n"
    "  } catch (e) {\n"
    "    $('#pill').className = 'pill off';\n"
    "    $('#pillTxt').textContent = '离线';\n"
    "    $('#sub').textContent = '无法连接，请确认设备与手机在同一 WiFi';\n"
    "    setBusy(false);\n"
    "    return null;\n"
    "  }\n"
    "}\n"
    "\n"
    "async function poll() {\n"
    "  const busyNow = await fetchStatus();\n"
    "  setTimeout(poll, busyNow === null ? 3000 : busyNow ? 1000 : 5000);\n"
    "}\n"
    "\n"
    "poll();\n"
    "log('控制台就绪');\n"
    "</script>\n"
    "</body>\n"
    "</html>\n";
